class Seats{int left=5; synchronized boolean book(){if(left>0){left--;return true;}return false;}}public class SeatBooking{public static void main(String[]x)throws Exception{Seats s=new Seats();Thread[] a=new Thread[10];int[] ok={0};for(int i=0;i<10;i++){a[i]=new Thread(()->{if(s.book())synchronized(ok){ok[0]++;}});a[i].start();}for(Thread t:a)t.join();System.out.println("Booked="+ok[0]+", left="+s.left);}}
